public void apacheShortLicenseShouldBeIdentifiedWithDifferentPreAndPostFixes() throws Exception {
    ApacheSoftwareLicense20 worker = new ApacheSoftwareLicense20();
    assertTrue(worker.matches(SHORT_LICENSE));
    assertTrue(worker.matches("# " + SHORT_LICENSE));
    assertTrue(worker.matches("##" + SHORT_LICENSE));
    assertTrue(worker.matches("##" + SHORT_LICENSE + "##"));
    assertTrue(worker.matches("/* " + SHORT_LICENSE + "*/"));
    assertTrue(worker.matches("/* " + SHORT_LICENSE + "*/"));
}

